'use strict';
const $ = (s, r=document) => r.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 endpoints:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',
 jobs:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M9 4V2m6 2V2M8 9h8m-8 4h8m-8 4h5"/>',
 lab:'<path d="M9 3h6m-5 0v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor" stroke="none"/><circle cx="15" cy="17" r="3" fill="currentColor" stroke="none"/>',
 plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="m9 5 7 7-7 7"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 speed:'<path d="M4 19a9 9 0 1 1 16 0M12 15l5-7M4 14h2m12 0h2M8 5l1 2"/><circle cx="12" cy="15" r="1"/>',
 check:'<path d="m8 12 3 3 5-6"/><path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z"/>', chart:'<path d="M4 3v17h17M7 15l4-5 4 2 5-7"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', play:'<path d="m8 4 12 8-12 8z"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v.1"/>',
 server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01"/>'
};
const icon=(name,size=18)=>`<svg class="ui-icon" xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]|| (name==='monitor'?paths.chart:paths.help)}</svg>`;
const names={overview:'实测总览',monitor:'模型巡检',endpoints:'接口管理',jobs:'测试记录',lab:'发起测试',settings:'工作台设置',help:'使用与指标说明'};
const states={ok:['完整响应','green'],error:['接口错误','red'],timeout:['请求超时','orange'],rate_limited:['触发限流','orange'],truncated:['输出截断','orange'],filtered:['内容过滤','orange'],empty:['空回答','orange'],cancelled:['已停止',''],unknown:['暂无数据',''],completed:['已完成','green'],running:['运行中','blue'],queued:['排队中','blue'],cancelling:['停止中','orange'],interrupted:['运行中断','orange'],failed:['任务异常','red']};
const profiles={short:'短输入',long_input:'长输入',long_output:'长输出',custom:'客户案例'};
const suites={quick:'快速体检',standard:'标准测速',quality:'能力回归',custom:'客户案例'};
let state={user:null,csrf:'',route:'overview',hours:24,endpoint:0,profile:'all',suite:'all',scenario:'all',endpoints:[],dashboard:null,refreshing:false,runEndpoint:0,inspectionHours:6,inspectionEndpoint:0,inspectionSort:'name'};
const badge=(status)=>`<span class="pill ${states[status]?.[1]||''}"><span class="dot"></span>${esc(states[status]?.[0]||status)}</span>`;
const num=(n,d=0)=>n==null?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const seconds=n=>n==null?'—':(n/1000).toFixed(2);
const date=(ts,full=false)=>ts?new Date(ts*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',...(full?{year:'numeric',month:'2-digit',day:'2-digit'}:{}),hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const ago=ts=>{if(!ts)return '尚未测试';const m=Math.max(0,Math.floor((Date.now()/1000-ts)/60));return m<1?'刚刚':m<60?`${m} 分钟前`:m<1440?`${Math.floor(m/60)} 小时前`:`${Math.floor(m/1440)} 天前`;};
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),6000);}
async function api(path,options={}){
 const headers={...(options.body!==undefined?{'Content-Type':'application/json'}:{}),...(options.method&&options.method!=='GET'?{'X-CSRF-Token':state.csrf}:{}),...options.headers};
 const {timeoutMs=12000,...requestOptions}=options;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),timeoutMs);
 let response;try{response=await fetch('/api'+path,{...requestOptions,headers,signal:controller.signal,body:options.body!==undefined?JSON.stringify(options.body):undefined});}catch(e){throw Error(e.name==='AbortError'?(path.endsWith('/discover')?'模型列表读取超时，请检查接口网络后重试。':'连接超时，请确认启动窗口仍在运行，再刷新页面。'):'无法连接后台，请确认词镜仍在运行。');}finally{clearTimeout(timeout);}
 let body;try{body=await response.json();}catch(e){throw Error('后台返回异常，请稍后重试。');}
 if(!response.ok){if(response.status===401&&state.user){state.user=null;showAuth(true);}
 let detail=body.detail;if(Array.isArray(detail))detail=detail.map(x=>`${x.loc?.slice(1).join('.')||'输入'}：${x.msg}`).join('；');throw Error(detail||'操作未完成');}return body;
}
function busy(button,work){if(!button)return work();const old=button.innerHTML;button.disabled=true;button.textContent='处理中…';return work().finally(()=>{button.disabled=false;button.innerHTML=old;});}
function heading(title,sub,actions=''){return `<div class="page-head"><h1>${title}</h1><div class="heading-actions">${actions}</div></div>`;}
function empty(title,desc,action=''){return `<div class="empty"><div class="empty-icon">${icon('chart',26)}</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function filterControls(extra=''){return extra?`<div class="control-bar"><div class="filters">${extra}</div></div>`:'';}
function showAuth(initialized,local=true){window.dispatchEvent(new Event('llmirror-ready'));$('#shell').hidden=true;$('#auth-screen').hidden=false;
 $('#auth-box').innerHTML=`<div class="eyebrow"></div><h2>${initialized?'登录':'首次设置'}</h2><p>${initialized?'':'设置管理员账号。'}</p>${!initialized&&!local?'<div class="form-error">首次配置需要在部署电脑上打开本地地址完成。</div>':''}<form id="auth-form"><div id="auth-error"></div><label class="field"><span>${initialized?'账号':'管理员账号'}</span><input name="username" autocomplete="username" placeholder="例如 admin" required minlength="2" maxlength="40" pattern="[a-zA-Z0-9_.@-]+"></label><label class="field"><span>密码</span><input name="password" type="password" autocomplete="${initialized?'current-password':'new-password'}" placeholder="至少 6 个字符" required minlength="6" maxlength="128"></label>${!initialized?'<label class="field"><span>确认密码</span><input type="password" name="confirm" autocomplete="new-password" placeholder="再输入一次密码" required minlength="6" maxlength="128"></label>':''}<button class="button primary" type="submit" ${!initialized&&!local?'disabled':''}>${initialized?'登录':'创建管理员'} </button></form><p class="auth-footnote">${initialized?'账号由工作台管理员创建。如忘记密码，请在部署电脑运行“重置密码.bat”。':''}</p>`;
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const f=new FormData(form);if(!initialized&&f.get('password')!==f.get('confirm')){$('#auth-error').innerHTML='<div class="form-error">两次密码输入不一致。</div>';return;}
 await busy($('button[type=submit]',form),async()=>{try{const user=await api('/auth/'+(initialized?'login':'setup'),{method:'POST',body:{username:f.get('username'),password:f.get('password')}});state.user=user;state.csrf=user.csrf;await enter();}catch(err){$('#auth-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}});});
}
async function enter(){state.endpoints=await api('/endpoints');$('#auth-screen').hidden=true;$('#shell').hidden=false;$('#username').textContent=state.user.username;$('#avatar').textContent=state.user.username[0].toUpperCase();$('#user-role').textContent={admin:'工作台管理员',member:'测试成员',viewer:'只读成员'}[state.user.role];$('#nav').innerHTML=Object.entries(names).filter(([k])=>k!=='help').map(([k,n])=>`<a class="nav-item" href="#${k}" data-nav="${k}">${icon(k)}<span class="nav-label">${n}</span></a>`).join('');state.route=Object.prototype.hasOwnProperty.call(names,location.hash.slice(1))?location.hash.slice(1):'overview';await render();}
async function render(){if(!state.user)return;state.route=Object.prototype.hasOwnProperty.call(names,location.hash.slice(1))?location.hash.slice(1):'overview';$('#top-title').textContent=names[state.route];document.title=names[state.route]+' · 词镜 llmirror';$$nav();$('#top-date').textContent=new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'});$('#main').innerHTML='<div class="loading"><span class="spinner"></span><p>正在读取工作台…</p></div>';try{await ({overview:renderOverview,monitor:renderMonitor,endpoints:renderEndpoints,jobs:renderJobs,lab:renderLab,settings:renderSettings,help:renderHelp}[state.route])();}catch(err){$('#main').innerHTML=`<div class="inline-error">${esc(err.message)}</div><button class="button" data-action="reload">重新加载</button>`;}}
function $$nav(){document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===state.route));}
function delta(curr,prev,lower=true){if(curr==null||prev==null||prev===0)return '<span class="delta">暂无可比基线</span>';const p=(curr-prev)/prev*100;return `<span class="delta ${(p<0)===lower?'good':'bad'}">${p>=0?'↑':'↓'} ${Math.abs(p).toFixed(1)}% 较前一周期</span>`;}
function metric(label,value,unit,ico,foot,change){return `<article class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ico,17)}</span></div><div class="metric-number num">${value}<small>${unit}</small></div><div class="metric-foot"><span>${foot}</span>${change}</div></article>`;}
function groupedEndpoints(endpoints){const groups=Object.create(null);for(const e of endpoints){const name=e.platform||'天翼云';(groups[name]||(groups[name]=[])).push(e);}return groups;}
function lineChart(buckets,field,color,id,unit,width,rangeHours=state.hours){
 const populated=buckets.filter(b=>b[field]!=null),latest=populated.at(-1),values=populated.map(b=>b[field]);
 const isLatency=field==='ttft_p90',display=v=>v==null?'—':isLatency?(v/1000).toFixed(2):num(v,field==='success_rate'?1:1);
 const main=$('#main'),styles=main?getComputedStyle(main):null;
 const available=main?main.clientWidth-parseFloat(styles.paddingLeft)-parseFloat(styles.paddingRight):1000;
 const hero=id==='latency-fill'||id==='inspection-speed',single=window.innerWidth<=900;
 const w=Math.max(280,Math.round((hero||single?available:(available-20)/2)-44)),h=hero?272:238,left=54,right=18,top=20,bottom=39;
 const peak=values.length?Math.max(...values):1,raw=isLatency?peak/1000:peak;
 const power=10**Math.floor(Math.log10(raw||1)),nice=[1,1.2,1.5,2,2.5,3,4,5,6,8,10,12,15,20].find(v=>v*power>=raw*1.15)||20;
 const max=field==='success_rate'?100:Math.max(power*nice*(isLatency?1000:1),isLatency?10:.1);
 const x=i=>left+i*(w-left-right)/Math.max(1,buckets.length-1),y=v=>h-bottom-v/max*(h-top-bottom);
 const fmtAxis=v=>isLatency?num(v/1000,v<1000?2:1):num(v,v<5?1:0);
 let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(unit)}历史趋势" style="height:${h}px"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".17"/><stop offset="1" stop-color="${color}" stop-opacity=".015"/></linearGradient></defs>`;
 for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#e9eef5" stroke-dasharray="${i?'3 5':'0'}"/><text x="${left-12}" y="${y(v)+4}" fill="#8795a8" font-size="12" text-anchor="end">${values.length?fmtAxis(v):'—'}</text>`;}
 let runs=[],run=[];buckets.forEach((b,i)=>{if(b[field]==null){if(run.length)runs.push(run);run=[];}else run.push([i,b[field]]);});if(run.length)runs.push(run);
 runs.forEach(points=>{const path=points.map(([i,v],j)=>`${j?'L':'M'}${x(i)},${y(v)}`).join(' ');if(points.length>1)svg+=`<path d="${path} L${x(points.at(-1)[0])},${h-bottom} L${x(points[0][0])},${h-bottom} Z" fill="url(#${id})"/><path d="${path}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;points.forEach(([i,v])=>{const recent=buckets[i]===latest;svg+=`${recent?`<circle cx="${x(i)}" cy="${y(v)}" r="8" fill="${color}" opacity=".12"/>`:''}<circle cx="${x(i)}" cy="${y(v)}" r="${recent?4.2:2.8}" fill="white" stroke="${color}" stroke-width="${recent?2.5:1.7}"/>`;});});
 const ticks=w<430?[0,.5,1]:[0,.25,.5,.75,1];
 [...new Set(ticks.map(n=>Math.round(n*(buckets.length-1))))].forEach(i=>{const b=buckets[i];if(!b)return;const label=new Date(b.time*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',...(rangeHours>=168?{month:'2-digit',day:'2-digit'}:{hour:'2-digit',minute:'2-digit',hour12:false})});svg+=`<text x="${x(i)}" y="${h-11}" fill="#8795a8" font-size="12" text-anchor="${i===0?'start':i===buckets.length-1?'end':'middle'}">${label}</text>`;});
 const metrics=b=>b&&b.count?`首输出 P90：${seconds(b.ttft_p90)} 秒\n生成速度：${num(b.tps_avg,1)} tokens/s\n完整响应：${num(b.success_rate,1)}%（${b.ok}/${b.count}）\n输出截断：${b.truncated||0} 次`:'无测试数据';
 const lastBucket=buckets.filter(b=>b.count>0).at(-1),step=(w-left-right)/Math.max(1,buckets.length-1);
 buckets.forEach((b,i)=>{const tip=`时段：${date(b.time,true)} 至 ${date(b.time+width,true)}\n${metrics(b)}\n\n最近有效时段：${lastBucket?date(lastBucket.time,true):'—'}\n${metrics(lastBucket)}`,encoded=esc(tip).replace(/\n/g,'&#10;');svg+=`<rect class="chart-hit" data-tip="${encoded}" aria-label="${encoded}" tabindex="0" x="${Math.max(left,x(i)-step/2)}" y="${top}" width="${i===0||i===buckets.length-1?step/2:step}" height="${h-top-bottom}" fill="transparent"/>`;});
 const stats=values.length?`<span>最低 <b>${display(Math.min(...values))}</b></span><span>最高 <b>${display(Math.max(...values))}</b></span>`:'<span>暂无有效样本</span>';
 return `<div class="trend-readout"><div><strong>${display(latest?.[field])}</strong><span>${esc(unit)}</span></div><div class="trend-range">${stats}</div></div><div class="trend-canvas">${svg}</svg>${!values.length?'<div class="trend-no-data"><span>暂无测试样本</span><a href="#lab">发起测试 →</a></div>':''}</div><div class="trend-foot"><span class="trend-key" style="--trend-color:${color}">最近有效时段 ${latest?date(latest.time):'—'}</span><span>${populated.length} 个有效时段 · 空缺不连线</span></div>`;
}

async function renderOverview(){state.endpoints=await api('/endpoints');const d=await api(`/dashboard?hours=${state.hours}&endpoint_id=${state.endpoint}&profile=${state.profile}&suite=${state.suite}&scenario=${state.scenario}`);state.dashboard=d;$('#top-node').textContent='● '+d.settings.node_name;const s=d.summary,p=s.previous;
 $('#main').innerHTML=heading('实测总览','观察已接入接口的速度、完整响应率与质量变化。',`<button class="button" data-action="refresh">${icon('refresh',15)} 刷新</button>${state.user.role!=='viewer'?`<a class="button primary" href="#lab">${icon('plus',16)} 发起测试</a>`:''}`)+filterControls(`<span class="update-label">${d.active_jobs?`${d.active_jobs} 个任务运行中`:'已更新 '+date(d.server_time)}</span><select id="endpoint-filter" aria-label="筛选接口"><option value="0">全部接口</option>${Object.entries(groupedEndpoints(state.endpoints)).map(([group,items])=>`<optgroup label="${esc(group)}">${items.map(e=>`<option value="${e.id}" ${state.endpoint===e.id?'selected':''}>${esc(e.name)} · ${esc(e.model)}</option>`).join('')}</optgroup>`).join('')}</select><select id="hours-filter" aria-label="时间范围">${[[6,'6 小时'],[24,'24 小时'],[168,'7 天'],[720,'30 天'],[2160,'90 天'],[8760,'365 天']].map(([h,label])=>`<option value="${h}" ${h===state.hours?'selected':''}>最近 ${label}</option>`).join('')}</select><select id="suite-filter" aria-label="测试类型"><option value="all">全部测试</option>${Object.entries(suites).map(([key,label])=>`<option value="${key}" ${state.suite===key?'selected':''}>${label}</option>`).join('')}</select><select id="scenario-filter" aria-label="应用场景"><option value="all">全部应用场景</option>${[['quality','能力回归'],['probe','标准模型巡检'],['chat','日常聊天'],['knowledge','知识库问答'],['workflow','智能体工作流']].map(([key,label])=>`<option value="${key}" ${state.scenario===key?'selected':''}>${label}</option>`).join('')}</select><select id="profile-filter" aria-label="输入类型"><option value="all">全部输入类型</option>${Object.entries(profiles).map(([key,label])=>`<option value="${key}" ${state.profile===key?'selected':''}>${label}</option>`).join('')}</select>`)+
 `<section class="metrics">${metric('首输出延迟 · P90',seconds(s.ttft_p90),'秒','clock',`P50 ${seconds(s.ttft_p50)}s · P95 ${seconds(s.ttft_p95)}s`,delta(s.ttft_p90,p.ttft_p90))}${metric('平均生成速度',num(s.tps_avg,1),'tokens/s','speed',`${s.tps_count} 个有效速度样本`,delta(s.tps_avg,p.tps_avg,false))}${metric('完整响应率',num(s.success_rate,1),'%','check',`${s.ok} / ${s.count} 次 · 截断 ${s.truncated||0} 次`,delta(s.success_rate,p.success_rate,false))}${metric('累计测试请求',num(s.count),'次','chart',`${s.quality_count} 份质量评分`,s.count>0&&s.count<30?'<span class="delta">样本较少 · 仅供初查</span>':'<span class="delta">所选时间范围内</span>')}</section>`+
 `<section class="charts chart-triple"><article class="panel"><div class="panel-head"><div><h2>首输出延迟趋势</h2><p>每个时间桶的 P90 · 包含截断样本</p></div><div class="legend"><span><i></i>首输出延迟 / 秒</span></div></div><div class="chart">${lineChart(d.buckets,'ttft_p90','#4775ed','latency-fill','秒',d.bucket_width)}</div></article><article class="panel"><div class="panel-head"><div><h2>生成速度趋势</h2><p>每个时间桶的平均值 · 不含等待首输出时间</p></div><div class="legend"><span><i style="background:#31a593"></i>tokens/s</span></div></div><div class="chart">${lineChart(d.buckets,'tps_avg','#31a593','speed-fill','tokens/s',d.bucket_width)}</div></article><article class="panel"><div class="panel-head"><div><h2>完整响应率趋势</h2></div><div class="legend"><span><i style="background:#8a6dd8"></i>完整响应 / %</span></div></div><div class="chart">${lineChart(d.buckets,'success_rate','#8a6dd8','success-fill','%',d.bucket_width)}</div></article></section><div id="chart-tooltip" class="chart-tooltip" hidden></div><div class="trend-note">悬停或聚焦图表查看时段数值及最新数据 · 当前保留 ${d.settings.retention_days} 天${s.cache_known?` · 缓存命中 ${s.cache_hit}/${s.cache_known}`:' · 缓存命中数据未返回'}。</div>`+
 `<section class="panel"><div class="panel-head"><div><h2>接口表现 <span class="pill">${d.endpoints.length} 个接口</span></h2><p>所选时间范围的实测汇总；不同场景混合时，请结合场景明细判断。</p></div><a class="text-button" href="#endpoints">管理接口</a></div>${d.endpoints.length?`<div class="table-wrap"><table><thead><tr><th>接口 / 模型</th><th>最近探测</th><th>首输出 P90</th><th>平均生成速度</th><th>完整响应率</th><th>质量通过率</th><th>样本</th><th></th></tr></thead><tbody>${d.endpoints.map(e=>`<tr><td><div class="row"><div class="endpoint-mark">API</div><div><strong>${esc(e.name)}</strong><small class="mono">${esc(e.model)}</small></div></div></td><td>${badge(e.last_status)}<small>${ago(e.last_seen)}${e.last_seen&&Date.now()/1000-e.last_seen>3600?' · 数据较旧':''}</small></td><td class="num">${seconds(e.ttft_p90)} <span class="muted">s</span></td><td class="num">${num(e.tps_avg,1)} <span class="muted small">tok/s</span></td><td>${num(e.success_rate,1)}${e.success_rate!=null?'%':''}<small>截断 ${e.truncated||0} 次</small></td><td>${num(e.quality_rate,0)}${e.quality_rate!=null?'%':''}<small>${e.quality_count?e.quality_count+' 份评分':'尚未回归'}</small></td><td>${e.count}<small>${e.count>0&&e.count<30?'样本较少':''}</small></td><td>${state.user.role!=='viewer'&&state.endpoints.some(x=>x.id===e.id)?`<button class="text-button" data-run="${e.id}">测试 </button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无接口','添加接口地址、模型名称和 API Key。',state.user.role==='admin'?'<button class="button primary" data-action="add-endpoint">添加接口</button>':'请联系管理员添加接口。')}<div class="table-footer"><span>完整响应率排除截断、过滤和空回答；已停止请求不计入分母。</span><span>API 端到端观测</span></div></section>`+
 (d.scenarios.length?`<div class="panel-head"><h2>场景明细</h2><span class="muted small">请优先比较同一模型、同一场景与参数</span></div><section class="scenario-grid">${d.scenarios.map(x=>`<article class="scenario-card"><h3>${esc(suites[x.suite]||x.suite)} · ${esc(profiles[x.profile]||x.profile)}</h3><p>${x.count} 次请求 · 完整响应 ${num(x.success_rate,1)}%</p><div class="row spread"><span><strong>${seconds(x.ttft_p90)}</strong><span class="muted small"> s / P90</span></span><span class="muted small">${num(x.tps_avg,1)} tok/s</span></div></article>`).join('')}</section>`:'')+
 `<div class="callout" style="margin-top:20px">${icon('help',15)} 指标按当前测试节点统计。<a href="#help"> 查看指标口径</a></div>`;
 $('#endpoint-filter').onchange=e=>{state.endpoint=+e.target.value;renderOverview().catch(e=>toast(e.message,true));};$('#hours-filter').onchange=e=>{state.hours=+e.target.value;renderOverview().catch(e=>toast(e.message,true));};$('#scenario-filter').onchange=e=>{state.scenario=e.target.value;renderOverview().catch(e=>toast(e.message,true));};$('#profile-filter').onchange=e=>{state.profile=e.target.value;renderOverview().catch(e=>toast(e.message,true));};$('#suite-filter').onchange=e=>{state.suite=e.target.value;renderOverview().catch(e=>toast(e.message,true));};
}
async function renderMonitor(){
 const [d,endpoints]=await Promise.all([api(`/inspections?hours=${state.inspectionHours}&endpoint_id=${state.inspectionEndpoint}`),api('/endpoints')]);
 state.endpoints=endpoints;
 const summary=d.summary,previous=summary.previous,admin=state.user.role==='admin',canRun=state.user.role!=='viewer';
 const ranges=[[6,'6小时'],[24,'24小时'],[168,'7天'],[720,'30天'],[2160,'90天'],[8760,'365天']];
 const period=ranges.find(([value])=>value===state.inspectionHours)?.[1]||'6小时';
 const items=[...d.endpoints].sort((a,b)=>state.inspectionSort==='speed'?(b.tps_avg??-1)-(a.tps_avg??-1):state.inspectionSort==='latency'?(a.ttft_p90??Infinity)-(b.ttft_p90??Infinity):state.inspectionSort==='reliability'?(b.success_rate??-1)-(a.success_rate??-1):(a.platform||'').localeCompare(b.platform||'','zh-CN')||a.model.localeCompare(b.model));
 function issues(e){const labels={error:'接口错误',timeout:'超时',rate_limited:'限流',truncated:'截断',empty:'空回答',filtered:'过滤'};return Object.entries(e.errors).filter(([,count])=>count).map(([status,count])=>`${labels[status]} ${count}`).join(' · ');}
 $('#main').innerHTML=heading('模型巡检','',`<button class="button" data-action="refresh">${icon('refresh',15)} 刷新</button>${canRun?`<button class="button primary" id="inspection-run-all" ${state.inspectionBatchBusy||!endpoints.length?'disabled':''}>${icon('play',15)} ${state.inspectionBatchBusy?'正在提交…':'全部立即巡检'}</button>`:''}<a class="button" href="#endpoints">配置定时巡检</a>`)+filterControls(`<span class="update-label">已更新 ${date(d.server_time)} · 今日总预算 ${d.budget_used}/${d.settings.daily_request_limit} 次</span><select id="inspection-model" aria-label="巡检模型"><option value="0">全部模型</option>${Object.entries(groupedEndpoints(endpoints)).map(([group,list])=>`<optgroup label="${esc(group)}">${list.map(e=>`<option value="${e.id}" ${state.inspectionEndpoint===e.id?'selected':''}>${esc(e.model)}</option>`).join('')}</optgroup>`).join('')}</select><select id="inspection-range" aria-label="巡检时间范围">${ranges.map(([value,label])=>`<option value="${value}" ${state.inspectionHours===value?'selected':''}>最近${label}</option>`).join('')}</select><select id="inspection-sort" aria-label="排序">${[['name','按平台 / 模型'],['speed','吞吐量从高到低'],['latency','延迟从低到高'],['reliability','可靠性从高到低']].map(([value,label])=>`<option value="${value}" ${state.inspectionSort===value?'selected':''}>${label}</option>`).join('')}</select>`)+
 `${d.budget_used>=d.settings.daily_request_limit?'<div class="notice">今日请求预算已用尽，后续定时巡检将跳过；可靠性仅统计已发出的请求。</div>':''}<section class="metrics">${metric('生成吞吐量',num(summary.tps_avg,1),'tokens/s','speed',`${summary.tps_count} 个有效测速样本`,delta(summary.tps_avg,previous.tps_avg,false))}${metric('首输出延迟 · P90',seconds(summary.ttft_p90),'秒','clock',`P50 ${seconds(summary.ttft_p50)}s · 正文 P50 ${seconds(summary.answer_p50)}s`,delta(summary.ttft_p90,previous.ttft_p90))}${metric(`可靠性 · 近${period}`,num(summary.success_rate,1),'%','check',`完整 ${summary.ok} / ${summary.count} 次`,delta(summary.success_rate,previous.success_rate,false))}${metric('巡检请求',num(summary.count),'次','chart',`已知用量 ${num(summary.tokens)} tokens`,summary.usage_missing?`<span class="delta">${summary.usage_missing} 条用量缺失</span>`:'<span class="delta">所选时段</span>')}</section>`+
 `<section class="panel inspection-panel"><div class="panel-head"><h2>模型表现</h2><span class="muted small">${items.length} 个模型 · 仅统计标准巡检</span></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>平台 / 模型</th><th>最近结果</th><th>吞吐量<small>tokens/s · 单请求</small></th><th>延迟<small>首输出 P90 / 秒</small></th><th>可靠性<small>近${period}</small></th><th>定时巡检</th><th>操作</th></tr></thead><tbody>${items.map(e=>`<tr><td><strong>${esc(e.model)}</strong><small>${esc(e.platform||'未分组')}${e.name!==e.model?' · '+esc(e.name):''}</small></td><td>${e.last_seen?badge(e.last_status):'<span class="muted">时段内无结果</span>'}<small>${ago(e.last_seen)}${e.stale?' · 数据较旧':''}</small></td><td class="num inspection-value">${num(e.tps_avg,1)}<small>${e.tps_count} 个有效样本</small></td><td class="num inspection-value">${seconds(e.ttft_p90)}<small>P50 ${seconds(e.ttft_p50)}s</small></td><td class="inspection-value ${e.success_rate==null?'':e.success_rate>=99?'inspection-good':e.success_rate>=95?'inspection-warn':'inspection-bad'}">${num(e.success_rate,1)}${e.success_rate==null?'':'%'}<small>完整 ${e.ok} / ${e.count}${e.count&&e.count<20?' · 样本较少':''}</small>${issues(e)?`<small class="inspection-issues">${esc(issues(e))}</small>`:''}</td><td>${e.schedule_minutes?'每 '+e.schedule_minutes+' 分钟':'未开启'}<small>${e.schedule_minutes?(e.schedule_scenario==='probe'?'标准巡检':'其他场景采样'):'建议每60分钟一次'}</small></td><td class="nowrap">${canRun?`<button class="text-button" data-inspection-run="${e.id}">立即巡检</button> `:''}<button class="text-button" data-inspection-trend="${e.id}">趋势</button>${e.last_job?` <button class="text-button" data-job="${e.last_job}">报告</button>`:''}${admin?` <button class="text-button" data-edit="${e.id}">设置</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无模型','添加接口并开启定时巡检。')}<div class="inspection-note">吞吐量为客户端观测的单请求生成速度，包含接口计入输出的思考 tokens；不代表平台最大并发吞吐。可靠性为完整响应数 / 实际巡检数，超时、错误、截断和空回答均不算完整响应，主动停止排除。</div></section>`+
 `<section class="charts chart-triple inspection-charts"><article class="panel"><div class="panel-head"><h2>吞吐量趋势</h2><span class="muted small">tokens/s</span></div><div class="chart">${lineChart(d.buckets,'tps_avg','#31a593','inspection-speed','tokens/s',d.bucket_width,state.inspectionHours)}</div></article><article class="panel"><div class="panel-head"><h2>延迟趋势</h2><span class="muted small">首输出 P90 / 秒</span></div><div class="chart">${lineChart(d.buckets,'ttft_p90','#4775ed','inspection-latency','秒',d.bucket_width,state.inspectionHours)}</div></article><article class="panel"><div class="panel-head"><h2>可靠性趋势</h2><span class="muted small">%</span></div><div class="chart">${lineChart(d.buckets,'success_rate','#8a6dd8','inspection-reliability','%',d.bucket_width,state.inspectionHours)}</div></article></section><div id="chart-tooltip" class="chart-tooltip" hidden></div><div class="trend-note">悬停查看历史值和最新值。每轮1次、约180字回答；输出少于64 tokens或生成区间短于0.5秒时，不纳入吞吐统计。建议按模型查看趋势；未开启巡检的模型不会自动产生调用。</div>`;
 $('#inspection-model').onchange=e=>{state.inspectionEndpoint=+e.target.value;renderMonitor().catch(err=>toast(err.message,true));};
 $('#inspection-range').onchange=e=>{state.inspectionHours=+e.target.value;renderMonitor().catch(err=>toast(err.message,true));};
 $('#inspection-sort').onchange=e=>{state.inspectionSort=e.target.value;renderMonitor().catch(err=>toast(err.message,true));};
 document.querySelectorAll('[data-inspection-trend]').forEach(button=>button.onclick=()=>{state.inspectionEndpoint=+button.dataset.inspectionTrend;renderMonitor().catch(err=>toast(err.message,true));});
 document.querySelectorAll('[data-inspection-run]').forEach(button=>button.onclick=async()=>{await busy(button,async()=>{try{await api('/jobs',{method:'POST',body:{endpoint_id:+button.dataset.inspectionRun,suite:'quick',scenario:'probe',count:1,concurrency:1}});toast('已发起1次巡检');}catch(err){toast(err.message,true);}});});
 const runAll=$('#inspection-run-all');
 if(runAll)runAll.onclick=async()=>{
  if(state.inspectionBatchBusy)return;
  state.inspectionBatchBusy=true;runAll.disabled=true;runAll.textContent='正在提交…';
  try{
   const result=await api('/inspections/run-all',{method:'POST',body:{},timeoutMs:45000});
   let message=`已发起 ${result.created} 次标准巡检`;
   if(result.skipped)message+=`；跳过 ${result.skipped} 个正在测试的模型`;
   if(result.unstarted)message+=`；${result.unstarted} 个未发起：${result.reason}`;
   if(!result.created&&!result.skipped&&!result.unstarted)message='暂无已接入模型';
   toast(message,!!result.unstarted);
  }catch(err){toast(err.message,true);}
  finally{state.inspectionBatchBusy=false;if(state.route==='monitor')await renderMonitor().catch(err=>toast(err.message,true));}
 };

}

async function renderEndpoints(){
 state.endpoints=await api('/endpoints');
 const endpoints=state.endpoints,admin=state.user.role==='admin';
 const groups=Object.entries(groupedEndpoints(endpoints));
 $('#main').innerHTML=heading('接口管理','',admin?`<button class="button" data-action="batch-models">批量添加模型</button><button class="button primary" data-action="add-endpoint">${icon('plus',16)} 添加接口</button>`:'')+filterControls()+
 (endpoints.length?`${admin?'<div class="endpoint-bulk-bar"><label class="endpoint-selection"><input type="checkbox" id="endpoint-select-all"><span>全选</span></label><span id="endpoint-selection-count" class="muted small">已选 0 个接口 / 0 个组</span><span class="spacer"></span><button class="button compact danger" id="delete-selected-endpoints" disabled>批量删除接口</button><button class="button compact danger" id="delete-selected-groups" disabled>批量删除接口组</button></div>':''}`+groups.map(([name,items],groupIndex)=>`<details class="panel platform-group" open><summary>${admin?`<label class="endpoint-selection group-selection"><input type="checkbox" data-group-select="${groupIndex}" aria-label="选择${esc(name)}组的全部接口"></label>`:''}<strong>${esc(name)}</strong><span class="pill">${items.length} 个模型</span>${admin?`<button class="text-button danger delete-platform" data-delete-group="${groupIndex}">删除接口组</button>`:''}</summary><div class="table-wrap"><table><thead><tr>${admin?'<th class="endpoint-check-cell"></th>':''}<th>名称 / 模型 ID</th><th>接口地址</th><th>凭证</th><th>定时采样</th><th>操作</th></tr></thead><tbody>${items.map(e=>`<tr>${admin?`<td class="endpoint-check-cell"><input type="checkbox" class="endpoint-checkbox" data-endpoint-select="${e.id}" data-group-index="${groupIndex}" aria-label="选择接口${esc(e.name)}"></td>`:''}<td><strong>${esc(e.name)}</strong><small class="mono">${esc(e.model)}</small>${e.tag?`<small>${esc(e.tag)}</small>`:''}</td><td class="mono">${esc(e.base_url)}</td><td>${e.has_key?'已保存':'未设置'}</td><td>${e.schedule_minutes?'每 '+e.schedule_minutes+' 分钟':'关闭'}${e.schedule_minutes?`<small>${esc({probe:'标准模型巡检',chat:'日常聊天',knowledge:'知识库问答',workflow:'智能体工作流'}[e.schedule_scenario]||'标准模型巡检')} · 约 ${Math.ceil(1440/e.schedule_minutes)} 次/天</small>`:''}<small>今日 ${e.scheduled_today_requests||0} 次 / 已知 ${num(e.scheduled_today_tokens||0)} tokens${e.scheduled_usage_missing?'（部分用量缺失）':''}</small></td><td class="nowrap">${state.user.role!=='viewer'?`<button class="text-button" data-run="${e.id}">测试</button> `:''}${admin?`<button class="text-button" data-edit="${e.id}">编辑</button> `:''}${admin?`<button class="text-button danger" data-delete="${e.id}">删除接口</button>`:''}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):`<section class="panel">${empty('暂无接口','添加接口后即可测试。',admin?'<button class="button primary" data-action="add-endpoint">添加接口</button>':'请联系管理员添加接口。')}</section>`);
 if(!admin||!endpoints.length)return;
 const rows=[...document.querySelectorAll('[data-endpoint-select]')],groupBoxes=[...document.querySelectorAll('[data-group-select]')],all=$('#endpoint-select-all');
 const chosenRows=()=>rows.filter(input=>input.checked),chosenGroups=()=>groupBoxes.filter(input=>input.checked);
 function updateSelection(){
  groupBoxes.forEach(input=>{const children=rows.filter(row=>row.dataset.groupIndex===input.dataset.groupSelect),count=children.filter(row=>row.checked).length;input.checked=count===children.length;input.indeterminate=count>0&&count<children.length;});
  const n=chosenRows().length,g=chosenGroups().length;all.checked=n===rows.length;all.indeterminate=n>0&&n<rows.length;
  $('#endpoint-selection-count').textContent=`已选 ${n} 个接口 / ${g} 个组`;$('#delete-selected-endpoints').disabled=!n;$('#delete-selected-groups').disabled=!g;
 }
 all.onchange=()=>{rows.forEach(input=>input.checked=all.checked);updateSelection();};
 rows.forEach(input=>input.onchange=updateSelection);
 groupBoxes.forEach(input=>input.onchange=()=>{rows.filter(row=>row.dataset.groupIndex===input.dataset.groupSelect).forEach(row=>row.checked=input.checked);updateSelection();});
 document.querySelectorAll('.group-selection').forEach(label=>label.addEventListener('click',event=>event.stopPropagation()));
 async function removed(result){state.endpoint=0;toast(`已删除 ${result.deleted} 个接口`);await renderEndpoints();}
 function deleteGroups(indices){
  const names=indices.map(index=>groups[index][0]),count=indices.reduce((sum,index)=>sum+groups[index][1].length,0);
  confirmDialog(names.length===1?'删除接口组？':'批量删除接口组？',`将删除${names.join('、')}组及组内全部接口（当前共 ${count} 个）。历史测试记录保留，定时采样停止。`,async()=>removed(await api('/endpoint-groups/delete',{method:'POST',body:{platforms:names}})));
 }
 $('#delete-selected-endpoints').onclick=()=>{const ids=chosenRows().map(input=>+input.dataset.endpointSelect);confirmDialog('批量删除接口？',`将删除选中的 ${ids.length} 个接口。历史测试记录保留，定时采样停止。`,async()=>removed(await api('/endpoints/delete',{method:'POST',body:{ids}})));};
 $('#delete-selected-groups').onclick=()=>deleteGroups(chosenGroups().map(input=>+input.dataset.groupSelect));
 document.querySelectorAll('[data-delete-group]').forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();deleteGroups([+button.dataset.deleteGroup]);});
}
function showDialog(html,wide=false){const d=$('#dialog');d.classList.toggle('wide',wide);$('#dialog-content').innerHTML=html;if(!d.open)d.showModal();}
const dialogHead=(title,sub='')=>`<div class="dialog-head"><div><h2>${title}</h2><p>${sub}</p></div><button class="close-dialog" data-action="close-dialog" aria-label="关闭">×</button></div>`;
function endpointDialog(e=null){showDialog(dialogHead(e?'编辑接口':'添加接口','支持 Chat Completions 兼容接口。')+`<form id="endpoint-form" class="dialog-body"><div id="endpoint-error"></div><div class="form-row"><label class="field"><span>接口名称 <b class="required">*</b></span><input name="name" required maxlength="60" placeholder="例如 天翼云 · 项目体验账号" value="${esc(e?.name||'')}"></label><label class="field"><span>备注 / 标签</span><input name="tag" maxlength="80" placeholder="例如 华东 / 按量计费" value="${esc(e?.tag||'')}"></label></div><label class="field"><span>平台分组</span><input name="platform" required maxlength="40" value="${esc(e?.platform||'天翼云')}" placeholder="例如 天翼云"></label><label class="field"><span>接口地址 <b class="required">*</b></span><input name="base_url" required type="url" placeholder="https://ai.ctaigw.cn/v1" value="${esc(e?.base_url||'')}"><small>支持 Base URL 或完整 /chat/completions 地址。</small></label><label class="field"><span>模型名称 / ID <b class="required">*</b></span><input name="model" required maxlength="120" placeholder="请从模型调用示例中复制" value="${esc(e?.model||'')}"></label><label class="field"><span>API Key / APP Key ${e?'<span class="field-label-note">留空保留原凭证</span>':''}</span><input name="api_key" type="password" autocomplete="new-password" placeholder="${e?'留空不修改':'只填写凭证本身，不包含 Bearer'}" maxlength="2048"><small>加密保存，不回显。</small></label><label class="field"><span>定时采样</span><select name="schedule_minutes">${[0,5,10,15,30,60,180,360,1440].map(m=>`<option value="${m}" ${(e?.schedule_minutes||0)===m?'selected':''}>${m?'每 '+m+' 分钟'+(m===60?'（推荐）':'')+' · 约 '+Math.ceil(1440/m)+' 次/天':'关闭'}</option>`).join('')}</select><small>建议每60分钟1次，单模型约24次/天。不自动重试，受每日请求预算限制。</small></label><label class="field"><span>定时采样场景</span><select name="schedule_scenario">${[['probe','标准模型巡检（推荐）· 短输入 / 约180字回答'],['chat','日常聊天 · 8,192 tokens / 180秒'],['knowledge','知识库问答 · 16,384 tokens / 300秒'],['workflow','智能体工作流 · 32,768 tokens / 480秒']].map(([key,label])=>`<option value="${key}" ${(e?.schedule_scenario||'probe')===key?'selected':''}>${label}</option>`).join('')}</select><small>标准巡检用于吞吐、首输出延迟和可靠性趋势；保留思考余量，按实际用量计费。</small></label><div class="form-actions"><button type="button" class="button" data-action="close-dialog">取消</button><button class="button primary" type="submit">保存接口</button></div></form>`);
 $('#endpoint-form').onsubmit=async event=>{event.preventDefault();const f=new FormData(event.target);await busy($('button[type=submit]',event.target),async()=>{try{await api('/endpoints'+(e?'/'+e.id:''),{method:e?'PUT':'POST',body:{name:f.get('name'),tag:f.get('tag'),platform:f.get('platform'),base_url:f.get('base_url'),model:f.get('model'),api_key:f.get('api_key'),schedule_minutes:+f.get('schedule_minutes'),schedule_scenario:f.get('schedule_scenario')}});$('#dialog').close();state.endpoint=0;toast('接口已保存');await render();}catch(err){$('#endpoint-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}});};}
function batchModelsDialog(){
 const sources=state.endpoints;
 showDialog(dialogHead('批量添加模型','填写一次接口地址和凭证，选择或粘贴模型 ID。')+`<form id="batch-models-form" class="dialog-body"><div id="batch-error"></div>
 <label class="field"><span>复用已有接口 <span class="field-label-note">可选</span></span><select name="source_id" id="batch-source"><option value="">新填写地址和凭证</option>${sources.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.model)}</option>`).join('')}</select><small>留空 Key 时复用所选接口的凭证。</small></label>
 <label class="field"><span>平台分组</span><input name="platform" id="batch-platform" maxlength="40" required value="天翼云" placeholder="例如 天翼云"></label><label class="field"><span>接口地址</span><input name="base_url" id="batch-url" type="url" value="https://ai.ctaigw.cn/v1" required><small>天翼云星辰地址可按控制台实际地址修改。</small></label>
 <label class="field"><span>API Key / APP Key</span><input name="api_key" type="password" autocomplete="new-password" placeholder="填写凭证；选择已有接口后可留空" maxlength="2048"></label>
 <div class="row wrap" style="margin-bottom:12px"><button class="button compact" type="button" id="discover-models">读取模型列表</button><span class="muted small">读取失败时可手动填写模型 ID。</span></div><div id="discovery-results"></div>
 <label class="field"><span>手动填写模型 ID <span class="field-label-note">每行一个</span></span><textarea name="models" rows="5" placeholder="例如：&#10;模型ID 1&#10;模型ID 2"></textarea></label>
 <label class="field"><span>统一备注 / 标签 <span class="field-label-note">可选</span></span><input name="tag" maxlength="80" placeholder="例如 天翼云"></label>
 <div class="form-actions"><button class="button" type="button" data-action="close-dialog">取消</button><button class="button primary" type="submit">添加选中模型</button></div></form>`);
 const form=$('#batch-models-form');
 $('#batch-source').onchange=e=>{const selected=sources.find(s=>s.id===+e.target.value);if(selected){$('#batch-url').value=selected.base_url;$('#batch-platform').value=selected.platform||'天翼云';$('[name=api_key]',form).value='';}$('#discovery-results').innerHTML='';};
 $('#discover-models').onclick=async event=>{const f=new FormData(form);$('#batch-error').innerHTML='';$('#discovery-results').innerHTML='';if(!String(f.get('api_key')||'').trim()&&!f.get('source_id')){$('#batch-error').innerHTML='<div class="form-error">请填写 API Key，或选择已有接口复用凭证。</div>';return;}await busy(event.currentTarget,async()=>{try{const result=await api('/endpoints/discover',{method:'POST',timeoutMs:45000,body:{base_url:f.get('base_url'),api_key:f.get('api_key'),source_id:f.get('source_id')?+f.get('source_id'):null}});$('#discovery-results').innerHTML=result.models.length?`<div class="field"><span>可选模型（${result.models.length}）</span><div class="model-options">${result.models.map(m=>`<label><input type="checkbox" name="selected_model" value="${esc(m)}"> <span>${esc(m)}</span></label>`).join('')}</div><div class="row"><button class="text-button" type="button" id="select-models">全选</button><button class="text-button" type="button" id="clear-models">清空</button></div></div>`:'<p class="muted small">接口没有返回模型，请手动填写。</p>';const check=$('#select-models'),clear=$('#clear-models');if(check)check.onclick=()=>form.querySelectorAll('[name=selected_model]').forEach(i=>i.checked=true);if(clear)clear.onclick=()=>form.querySelectorAll('[name=selected_model]').forEach(i=>i.checked=false);}catch(err){$('#batch-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}});};
 form.onsubmit=async event=>{event.preventDefault();const f=new FormData(form);const models=[...new Set([...f.getAll('selected_model'),...String(f.get('models')).split(/[\r\n,，]+/)].map(x=>x.trim()).filter(Boolean))];if(!models.length){$('#batch-error').innerHTML='<div class="form-error">请先选择或填写模型 ID。</div>';return;}if(models.length>100){$('#batch-error').innerHTML='<div class="form-error">单次最多添加 100 个模型。</div>';return;}await busy($('button[type=submit]',form),async()=>{try{const result=await api('/endpoints/batch',{method:'POST',body:{base_url:f.get('base_url'),api_key:f.get('api_key'),source_id:f.get('source_id')?+f.get('source_id'):null,models,tag:f.get('tag'),platform:f.get('platform')}});$('#dialog').close();state.endpoint=0;toast(`已添加 ${result.created.length} 个模型，跳过 ${result.skipped.length} 个重复项`);await render();}catch(err){$('#batch-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}});};
}
const jobSelection={owner:null,ids:new Set()};
function canDeleteJob(job){return !['running','queued','cancelling'].includes(job.status)&&(state.user.role==='admin'||(state.user.role==='member'&&state.user.username===job.owner));}
async function renderJobs(){
 const username=state.user.username,jobs=await api('/jobs');
 if(state.route!=='jobs'||state.user?.username!==username)return;
 const canSelect=state.user.role!=='viewer',eligible=new Set(jobs.filter(canDeleteJob).map(j=>j.id));
 if(jobSelection.owner!==username){jobSelection.owner=username;jobSelection.ids.clear();}
 for(const id of jobSelection.ids)if(!eligible.has(id))jobSelection.ids.delete(id);
 $('#main').innerHTML=heading('测试记录','',canSelect?`<a class="button primary" href="#lab">${icon('plus',16)} 发起测试</a>`:'')+
 filterControls('<span class="live-indicator"><i></i>运行状态自动更新</span>')+
 (canSelect&&jobs.length?`<div class="endpoint-bulk-bar job-bulk-bar"><label class="endpoint-selection"><input type="checkbox" id="job-select-all" ${eligible.size?'':'disabled'}><span>全选当前列表</span></label><span id="job-selection-count" class="muted small" aria-live="polite"></span><span class="spacer"></span><button class="button compact danger" id="delete-selected-jobs" disabled>批量删除</button></div>`:'')+
 `<section class="panel">${jobs.length?`<div class="table-wrap"><table class="jobs-table"><thead><tr>${canSelect?'<th class="endpoint-check-cell"><span class="sr-only">选择记录</span></th>':''}<th>测试 / 接口</th><th>场景</th><th>状态</th><th>进度</th><th>发起人 / 节点</th><th>北京时间</th><th>操作</th></tr></thead><tbody>${jobs.map(j=>`<tr class="${jobSelection.ids.has(j.id)?'job-selected':''}">${canSelect?`<td class="endpoint-check-cell"><input type="checkbox" class="endpoint-checkbox job-checkbox" data-job-select="${esc(j.id)}" aria-label="选择${esc(j.endpoint_name)}的测试记录" ${canDeleteJob(j)?'':'disabled title="仅可删除有权限且已结束的任务"'} ${jobSelection.ids.has(j.id)?'checked':''}></td>`:''}<td><strong>${esc(j.endpoint_name)}</strong>${j.temporary?'<span class="pill private-job">临时 · 仅本人</span>':''}<small class="mono">${esc(j.model)}</small></td><td>${esc(suites[j.suite])}<small>${esc(profiles[j.profile])}</small></td><td>${badge(j.status)}</td><td><span class="num">${j.completed} / ${j.planned}</span><div class="job-progress"><i style="width:${Math.min(100,j.completed/j.planned*100)}%"></i></div></td><td>${esc(j.owner)}<small>${esc(j.node)}</small></td><td class="nowrap">${date(j.created,true)}</td><td class="nowrap"><button class="text-button" data-job="${j.id}">查看</button> ${['running','queued','cancelling'].includes(j.status)&&(state.user.role==='admin'||(canSelect&&state.user.username===j.owner))?`<button class="text-button danger" data-cancel="${j.id}">停止</button>`:`<a class="text-button" href="/api/export/${j.id}" download>导出</a>`}${canDeleteJob(j)?` <button class="text-button danger" data-delete-job="${j.id}">删除</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无测试记录','发起测试后查看记录。',canSelect?'<a class="button primary" href="#lab">发起测试</a>':'')}<div class="table-footer"><span>最近 50 个任务${canSelect?' · 仅可勾选有权限且已结束的记录':''}</span><span>取消与中断的请求可能已产生平台用量</span></div></section>`;
 if(!canSelect||!jobs.length)return;
 const inputs=[...document.querySelectorAll('[data-job-select]:not(:disabled)')],all=$('#job-select-all'),button=$('#delete-selected-jobs');
 function updateSelection(){
  for(const input of inputs){input.checked=jobSelection.ids.has(input.dataset.jobSelect);input.closest('tr').classList.toggle('job-selected',input.checked);}
  const n=jobSelection.ids.size;all.checked=!!inputs.length&&n===inputs.length;all.indeterminate=n>0&&n<inputs.length;
  $('#job-selection-count').textContent=`已选 ${n} 条`;button.disabled=!n;
 }
 for(const input of inputs)input.onchange=()=>{if(input.checked)jobSelection.ids.add(input.dataset.jobSelect);else jobSelection.ids.delete(input.dataset.jobSelect);updateSelection();};
 all.onchange=()=>{jobSelection.ids.clear();if(all.checked)for(const input of inputs)jobSelection.ids.add(input.dataset.jobSelect);updateSelection();};
 button.onclick=()=>{
  const ids=[...jobSelection.ids];if(!ids.length)return;
  confirmDialog(`删除选中的 ${ids.length} 条测试记录？`,'对应任务及请求样本将永久删除，看板统计会同步更新。此操作无法撤销。',async()=>{
   const result=await api('/jobs/delete',{method:'POST',body:{ids}});jobSelection.ids.clear();toast(`已删除 ${result.deleted} 条测试记录`);await renderJobs();
  });
 };
 updateSelection();
}

async function renderLab(selected=0){
 selected=selected||state.runEndpoint;if(selected)state.useTemporary=false;state.runEndpoint=0;state.endpoints=await api('/endpoints');
 if(state.user.role==='viewer'){$('#main').innerHTML=heading('发起测试','')+empty('只读账号','发起测试需要成员或管理员权限。');return;}
 const [scenarioDefs,qualityCases,tempBudget]=await Promise.all([api('/scenarios'),api('/cases'),api('/temporary/budget')]);const presets=Object.fromEntries(Object.entries(scenarioDefs).filter(([,p])=>!p.scheduled_only));const caseCount=qualityCases.length;
 $('#main').innerHTML=heading('发起测试','')+`<div class="grid-main"><section class="panel"><div class="panel-head"><h2>测试配置</h2><span class="pill blue">无自动重试</span></div><form id="run-form" class="panel-body"><div id="run-error"></div>
<div class="test-source-tabs" role="group" aria-label="测试接口来源"><button type="button" data-source="saved">团队公共接口</button><button type="button" data-source="temporary">临时接口测试 <span>仅本人</span></button></div>
<section id="temporary-source" class="temporary-source" hidden>
 <div class="temporary-heading"><strong>临时接口</strong><span class="pill blue">凭证不保存 · 记录仅本人可见</span></div>
 <label class="field"><span>接口地址 <b class="required">*</b></span><input type="url" name="temporary_url" placeholder="https://api.example.com/v1" maxlength="500"></label>
 <label class="field"><span>API Key</span><input type="password" name="temporary_key" autocomplete="off" maxlength="2048" placeholder="只用于当前任务，不保存凭证"></label>
 <div class="temporary-model-row"><label class="field"><span>模型 ID <b class="required">*</b></span><input name="temporary_model" list="temporary-model-list" maxlength="120" placeholder="填写或读取模型 ID"><datalist id="temporary-model-list"></datalist></label><button class="button" type="button" id="temporary-discover">读取模型列表</button></div>
 <p class="small muted" id="temporary-budget"></p><p class="small muted">凭证在任务结束后释放；临时接口不加入公共列表，不开启定时巡检。测试成员仅可调用公网地址。</p>
</section>
<div id="saved-source"> <label class="field"><span>选择接口 <b class="required">*</b></span><select name="endpoint_id" id="run-endpoint" required>${state.endpoints.length?Object.entries(groupedEndpoints(state.endpoints)).map(([group,items])=>`<optgroup label="${esc(group)}">${items.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.model)}</option>`).join('')}</optgroup>`).join(''):'<option value="">请先添加接口</option>'}</select></label>
</div>
 <div class="form-row"><label class="field"><span>测试类型</span><select name="suite" id="run-suite"><option value="quick">快速体检 · 默认5次</option><option value="standard">标准测速 · 默认100次</option><option value="quality">能力回归 · ${caseCount}道推理题</option><option value="custom">客户案例 · 自定义输入</option></select></label><label class="field"><span>应用场景</span><select name="scenario" id="run-scenario">${Object.entries(presets).map(([key,p])=>`<option value="${key}">${esc(p.label)}</option>`).join('')}</select></label></div>
 <div id="scenario-summary" class="scenario-summary"></div>
 <div class="form-row"><label class="field"><span id="count-label">请求次数</span><input type="number" name="count" id="run-count" value="5" min="1" max="200" required></label><label class="field"><span>任务并发</span><input type="number" name="concurrency" value="1" min="1" max="16" required><small>受全局并发上限约束。</small></label></div>
 <label class="field" id="custom-prompt-field" hidden><span>客户问题 / 测试提示词</span><textarea name="prompt" rows="5" maxlength="40000" placeholder="填写脱敏问题，或在高级参数中提供 messages。"></textarea></label>
 <details class="subsection"><summary>高级参数与客户案例</summary><label class="field"><span>额外请求参数 JSON</span><textarea name="extra" class="mono" rows="5" placeholder='例如 {"thinking":{"type":"enabled"}} 或 {"messages":[{"role":"user","content":"你好"}]}'></textarea><small>支持思考模式、messages、top_p、response_format 等；输出上限和超时由场景统一配置。</small></label></details>
 <div id="run-estimate" class="run-estimate"></div><p class="small muted" style="margin-bottom:12px">内置业务题依次轮换；客户案例和质量题保持原样。</p><button class="button primary" type="submit" ${state.endpoints.length?'':'disabled'}>${icon('play',15)} 开始测试</button><span class="muted small" style="margin-left:12px">后台执行</span></form></section>
 <aside class="stack"><section class="panel"><div class="panel-head"><h2>场景说明</h2></div><div class="panel-body" style="padding-top:0">${Object.entries(presets).map(([key,p],i)=>`<div class="guide-step"><span>0${i+1}</span><div><h3>${esc(p.label)}</h3><p>${esc(p.description)}。<br>输出上限 ${num(p.max_tokens)} tokens · 超时 ${p.timeout} 秒</p></div></div>`).join('')}</div></section><section class="panel"><div class="panel-body"><h3>测试范围</h3><p class="muted small" style="margin-top:10px;line-height:2">知识库和工作流使用合成业务材料，测量单次模型调用；不包含检索耗时或真实工具执行。能力回归使用独立题库，不传输出长度上限，保留单题超时保护。</p><a class="text-button" href="#help">指标说明</a></div></section></aside></div>`;
 const form=$('#run-form');const preferred=state.endpoints.find(e=>e.id===selected)||state.endpoints[0];if(preferred)$('#run-endpoint').value=preferred.id;
 const temporaryFields=$('#temporary-source');
 function chooseSource(temporary){
  state.useTemporary=temporary;temporaryFields.hidden=!temporary;$('#saved-source').hidden=temporary;
  temporaryFields.querySelectorAll('input').forEach(input=>input.disabled=!temporary);
  form.elements.temporary_url.required=temporary;form.elements.temporary_model.required=temporary;
  $('#run-endpoint').disabled=temporary;$('#run-endpoint').required=!temporary;
  $('button[type=submit]',form).disabled=!temporary&&!state.endpoints.length;
  form.querySelectorAll('[data-source]').forEach(button=>{button.classList.toggle('selected',(button.dataset.source==='temporary')===temporary);button.setAttribute('aria-pressed',String((button.dataset.source==='temporary')===temporary));});
 }
 $('#temporary-budget').textContent=`本人今日临时请求预留 ${tempBudget.used} / ${tempBudget.limit} 次，同时计入全局预算。`;
 form.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>chooseSource(button.dataset.source==='temporary'));
 $('#temporary-discover').onclick=async event=>busy(event.target,async()=>{try{const base_url=form.elements.temporary_url.value.trim(),api_key=form.elements.temporary_key.value.trim();if(!base_url)throw Error('请填写接口地址');const result=await api('/temporary/discover',{method:'POST',body:{base_url,api_key},timeoutMs:45000});$('#temporary-model-list').innerHTML=result.models.map(model=>`<option value="${esc(model)}"></option>`).join('');if(result.models.length&&!form.elements.temporary_model.value)form.elements.temporary_model.value=result.models[0];toast(`读取到 ${result.models.length} 个模型，可在模型 ID 中选择或输入。`);}catch(err){toast(err.message,true);}});
 chooseSource(Boolean(state.useTemporary||!state.endpoints.length));
 function estimate(){const f=new FormData(form),quality=f.get('suite')==='quality',p=quality?scenarioDefs.quality:presets[f.get('scenario')],count=+f.get('count')||0,n=quality?count*caseCount:count,ep=state.endpoints.find(e=>e.id===+f.get('endpoint_id'));$('#scenario-summary').innerHTML=`<strong>${esc(p.label)}</strong><span>${quality?'本工具不传输出上限':'单次输出上限 '+num(p.max_tokens)+' tokens'} · 超时 ${p.timeout} 秒</span><small>${quality?'可充分推理，按最终答案评分；接口仍可能自行截断。':'Temperature 沿用模型默认值，输出预算预留思考与正文空间。'}</small>`;$('#run-estimate').innerHTML=`<span>计划请求<strong>${n} 次${quality?'（'+caseCount+'题 × '+count+'遍）':''}</strong></span><span>${quality?'输出额度':'输出预算上限'}<strong>${quality?'由模型接口控制':num(n*p.max_tokens)+' tokens'}</strong></span><span>按实际用量计费，另计输入 tokens</span>`;}
 $('#run-suite').onchange=e=>{const suite=e.target.value;$('#run-count').value=suite==='standard'?100:suite==='quality'?1:5;$('#run-count').max=suite==='quality'?5:200;$('#count-label').textContent=suite==='quality'?'每题重复次数':'请求次数';$('#custom-prompt-field').hidden=suite!=='custom';$('#run-scenario').disabled=suite==='quality';estimate();};form.addEventListener('input',estimate);form.addEventListener('change',estimate);estimate();
 form.onsubmit=async event=>{event.preventDefault();const f=new FormData(form);let extra={};try{extra=f.get('extra').trim()?JSON.parse(f.get('extra')):{};if(!extra||Array.isArray(extra)||typeof extra!=='object')throw Error();}catch(e){$('#run-error').innerHTML='<div class="form-error">高级参数需要是有效的 JSON 对象。</div>';return;}
 const custom=f.get('suite')==='custom',body={endpoint_id:+f.get('endpoint_id'),suite:f.get('suite'),scenario:f.get('suite')==='quality'?'chat':f.get('scenario'),profile:custom?'custom':'short',count:+f.get('count'),concurrency:+f.get('concurrency'),prompt:custom?f.get('prompt')||'':'',extra};
 if(custom&&!body.prompt.trim()&&!extra.messages){$('#run-error').innerHTML='<div class="form-error">客户案例需要填写提示词或 messages。</div>';return;}
 await busy($('button[type=submit]',form),async()=>{try{if(state.useTemporary)body.temporary_endpoint={name:'临时接口 · '+form.elements.temporary_model.value.trim().slice(0,40),base_url:form.elements.temporary_url.value.trim(),model:form.elements.temporary_model.value.trim(),api_key:form.elements.temporary_key.value.trim()};const job=await api(state.useTemporary?'/temporary/jobs':'/jobs',{method:'POST',body});form.elements.temporary_key.value='';toast(`已创建任务，共 ${job.planned} 次请求`);location.hash='jobs';}catch(err){$('#run-error').innerHTML=`<div class="form-error">${esc(err.message)}</div>`;}});};
}
function readablePrompt(value){
 try{
  const messages=JSON.parse(value);
  if(Array.isArray(messages)&&messages.every(m=>m&&typeof m==='object'&&typeof m.content==='string')){
   const roles={system:'系统',user:'用户',assistant:'助手'};
   return messages.map(m=>`【${roles[m.role]||m.role||'消息'}】\n${m.content}`).join('\n\n');
  }
 }catch(e){}
 return value||'（无内容）';
}
async function jobDialog(jid){const j=await api('/jobs/'+jid);const samples=j.samples;const ok=samples.filter(s=>s.status==='ok');const cut=samples.filter(s=>s.status==='truncated');const measured=[...ok,...cut];const avg=(field)=>{const a=measured.filter(s=>s[field]!=null);return a.length?a.reduce((n,s)=>n+s[field],0)/a.length:null;};const scored=samples.filter(s=>s.quality_pass!=null);const c=JSON.parse(j.config);showDialog(dialogHead(esc(j.endpoint_name)+' · 测试报告',`${esc(suites[j.suite])} · ${esc(j.model)} · ${date(j.created,true)} · ${esc(j.node)}`)+`<div class="dialog-body"><div class="row spread" style="margin-bottom:18px"><div class="row">${badge(j.status)}<span class="muted small">已完成 ${j.completed} / ${j.planned} 次</span></div><div class="row"><button class="text-button" data-job="${j.id}">刷新报告</button><a class="button compact" href="/api/export/${j.id}" download>${icon('download',13)} 导出脱敏 CSV</a></div></div><div class="detail-metrics"><div><span>完整响应</span><strong>${ok.length} / ${samples.filter(s=>s.status!=='cancelled').length}</strong><small class="muted">截断 ${cut.length} 次</small></div><div><span>平均首输出</span><strong>${seconds(avg('ttft_ms'))} <small>s</small></strong></div><div><span>平均生成速度</span><strong>${num(avg('tps'),1)}</strong></div><div><span>质量评分</span><strong>${scored.length?scored.reduce((n,s)=>n+s.quality_pass,0)+' / '+scored.length:'—'}</strong></div></div><div class="callout">${esc(c.scenario_label||'旧版配置')} · 任务并发 ${c.concurrency??'—'} · ${c.max_tokens==null?'输出上限由模型接口控制':'输出上限 '+num(c.max_tokens)+' tokens'} · 超时 ${c.timeout??'—'} 秒 · Temperature ${c.temperature??'模型默认'}<br>首输出和速度包含截断样本；完整响应与截断分别统计。能力评分仅包含可提取最终答案的完整回答。${j.temporary?' 本任务仅本人可见，凭证未保存。':''}${j.suite==='quality'?' 题库：'+esc(c.quality_version||'原题库'):''}</div><details class="sample-detail"><summary>查看本次请求配置</summary><pre>${esc(JSON.stringify(c,null,2))}</pre></details><h3 style="margin:22px 0 10px">请求样本 <span class="muted small">${samples.length} 条</span></h3>${samples.length?samples.map((s,i)=>`<details class="sample-detail"><summary><span class="row wrap"><strong>#${i+1} ${esc(s.case_name||'性能测试')}</strong>${badge(s.status)}<span>首输出 ${seconds(s.ttft_ms)}s</span><span>${num(s.tps,1)} tok/s</span>${s.quality_pass!=null?`<span class="pill ${s.quality_pass?'green':'red'}">${s.quality_pass?'评分通过':'评分未通过'}</span>`:''}</span></summary><ul class="info-list"><li><span>正文首输出 / 最后输出 / 完整连接</span><strong>${seconds(s.answer_ms)}s / ${seconds(s.e2e_ms)}s / ${seconds(s.finish_ms)}s</strong></li><li><span>工具内排队 / 最大数据块间隔</span><strong>${seconds(s.queue_ms)}s / ${seconds(s.max_gap_ms)}s</strong></li><li><span>输入 / 输出 / 缓存 / 思考 tokens</span><strong>${num(s.prompt_tokens)} / ${num(s.output_tokens)} / ${num(s.cached_tokens)} / ${num(s.reasoning_tokens)}</strong></li><li><span>用量来源 / HTTP / 结束原因</span><strong>${esc(s.token_source)} / ${s.http_status??'—'} / ${esc(s.finish_reason||'—')}</strong></li><li><span>请求 ID</span><strong class="mono">${esc(s.request_id||'—')}</strong></li></ul>${s.error?`<div class="form-error" style="margin-top:12px">${esc(s.error)}</div>`:''}${s.quality_note?`<p class="small muted" style="margin-top:10px">${esc(s.quality_note)}</p>`:''}<h3>请求内容</h3><pre>${esc(readablePrompt(s.prompt))}</pre>${s.prompt&&s.prompt.trim().startsWith('[')?`<details class="sample-detail"><summary>查看原始消息 JSON</summary><pre>${esc(s.prompt)}</pre></details>`:''}${s.reasoning?`<h3>思考内容</h3><pre>${esc(s.reasoning)}</pre>`:''}<h3>回答内容</h3><pre>${esc(s.response||'（无正文）')}</pre></details>`).join(''):empty('测试正在执行','完成第一条请求后，点击刷新报告查看样本。')}</div>`,true);}
async function renderSettings(){const s=await api('/settings');const admin=state.user.role==='admin';const users=admin?await api('/users'):[];$('#main').innerHTML=heading('工作台设置','管理测试节点、用量预算、数据保留与同事账号。')+`<div class="${state.user.role==='viewer'?'':'grid-two'}"><section class="panel"><div class="panel-head"><h2>运行与数据</h2><span class="pill blue">SQLite · 本地存储</span></div><form id="settings-form" class="panel-body"><label class="field"><span>测试节点名称</span><input name="node_name" value="${esc(s.node_name)}" required maxlength="80" ${admin?'':'disabled'}><small>例如 上海 · 天翼云公网节点，或 客户A · 办公网。</small></label><div class="form-row"><label class="field"><span>全局并发上限</span><input type="number" name="global_concurrency" min="1" max="16" value="${s.global_concurrency}" required ${admin?'':'disabled'}></label><label class="field"><span>每日真实请求预算</span><input type="number" name="daily_request_limit" min="1" max="20000" value="${s.daily_request_limit}" required ${admin?'':'disabled'}></label></div><label class="field"><span>每人每日临时接口请求上限</span><input type="number" name="temporary_daily_request_limit" min="1" max="20000" value="${s.temporary_daily_request_limit||100}" required ${admin?'':'disabled'}><small>临时接口请求另计个人上限，并占用全局预算。</small></label><label class="field"><span>数据保留天数</span><input type="number" name="retention_days" min="1" max="365" value="${s.retention_days}" required ${admin?'':'disabled'}><small>每小时清理过期已结束任务及样本。</small></label><div class="callout">预算按北京时间每日重置；创建任务时预留请求数，取消或中断不返还当日预留。</div>${admin?'<div class="form-actions"><button class="button primary" type="submit">保存设置</button></div>':''}</form></section><div class="stack">${admin?`<section class="panel"><div class="panel-head"><h2>本地备份</h2></div><div class="panel-body"><p class="muted small" style="line-height:2">备份保存到 data/backups，包含数据库和凭证密钥。</p><div class="row" style="margin-top:18px"><button class="button" data-action="backup">${icon('download',15)} 创建备份</button><button class="text-button" data-action="cleanup">立即清理过期数据</button></div><p class="small muted" style="margin-top:14px">备份含凭证密钥，请妥善保管。</p></div></section>`:''}${state.user.role!=='viewer'?`<section class="panel"><div class="panel-head"><h2>修改我的密码</h2></div><form id="password-form" class="panel-body"><label class="field"><span>当前密码</span><input type="password" name="current" autocomplete="current-password" required></label><label class="field"><span>新密码</span><input type="password" name="password" minlength="6" maxlength="128" autocomplete="new-password" required placeholder="至少6个字符"></label><button class="button" type="submit">更新密码并重新登录</button></form></section>`:''}</div></div>${admin?`<section class="panel" style="margin-top:22px"><div class="panel-head"><div><h2>同事账号</h2><p></p></div><button class="button compact" data-action="add-user">${icon('plus',14)} 添加账号</button></div><div class="table-wrap"><table><thead><tr><th>账号</th><th>权限</th><th>创建时间</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.username)}</strong>${u.id===state.user.id?'<span class="pill" style="margin-left:8px">当前账号</span>':''}</td><td>${{admin:'管理员',member:'测试成员',viewer:'只读成员'}[u.role]}</td><td>${date(u.created,true)}</td><td>${u.id!==state.user.id?`<button class="text-button danger" data-delete-user="${u.id}" data-username="${esc(u.username)}">删除</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;
 if(admin)$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await busy($('button[type=submit]',e.target),async()=>{try{await api('/settings',{method:'PUT',body:{node_name:f.get('node_name'),global_concurrency:+f.get('global_concurrency'),daily_request_limit:+f.get('daily_request_limit'),retention_days:+f.get('retention_days'),temporary_daily_request_limit:+f.get('temporary_daily_request_limit')}});$('#top-node').textContent='● '+f.get('node_name');toast('运行设置已保存');}catch(err){toast(err.message,true);}});};
 if($('#password-form'))$('#password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await busy($('button[type=submit]',e.target),async()=>{try{await api('/auth/password',{method:'POST',body:{current:f.get('current'),password:f.get('password')}});toast('密码已更新，请重新登录');state.user=null;showAuth(true);}catch(err){toast(err.message,true);}});};}
async function renderHelp(){const cases=await api('/cases');$('#main').innerHTML=heading('使用说明','这是一套外部接口观测工具；它记录可复现的现象，帮助缩小排查范围。')+`<div class="grid-main"><section class="panel"><div class="panel-body help-content"><h2>词镜 llmirror</h2><p>番禺电信集成交付团队 · 研发出品</p><h2>快速开始</h2><p>在「接口管理」添加平台提供的实际地址、模型名称和凭证。先运行5次快速体检；确认接口支持流式输出后，再做100次同场景测速或${cases.length}题能力回归。报告可在「测试记录」中导出。</p><h2>指标怎么计算</h2><table><thead><tr><th>指标</th><th>本工具口径</th></tr></thead><tbody><tr><td>首输出延迟</td><td>从实际发出请求到第一段非空思考或正文内容。不把空事件、角色字段或心跳算作输出。</td></tr><tr><td>正文首输出</td><td>从请求发出到第一段非空正文；仅在接口区分思考与正文时可明确观察。</td></tr><tr><td>生成速度</td><td>（接口返回的输出 tokens − 1）÷（最后一段有效输出时间 − 第一段有效输出时间）。为基于流式接收的近似值；数据块不等于单个 token。</td></tr><tr><td>完整回答耗时</td><td>请求发出到最后一段有效输出。另存完整连接耗时，包含末尾用量和结束事件。</td></tr><tr><td>输出上限与场景</td><td>日常聊天 8,192、知识库问答 16,384、智能体工作流 32,768 tokens；超时分别为 180、300、480 秒。上限预留思考与正文空间，不保证一定完整，受服务商限制及思考用量影响。</td></tr><tr><td>完整响应率</td><td>完整、非空、未截断且未过滤的回答数 ÷ 已尝试请求数。已停止请求排除；HTTP 200 后的流式错误也算失败。</td></tr><tr><td>P50 / P90 / P95</td><td>对完整及截断样本的首输出延迟排序后线性插值；较高分位数反映慢请求。小样本易波动。</td></tr><tr><td>质量通过率</td><td>固定题库中最终答案正确的完整回答数 ÷ 可评分完整回答数；推理正文不参与字符串匹配。网络错误、空回答、截断及无法提取最终答案的样本单列，不计入能力评分。</td></tr><tr><td>缓存与思考 tokens</td><td>仅采用接口真实返回字段；缺失显示“—”，不推断支持或不支持。</td></tr></tbody></table><h2>比较结果时注意什么</h2><ul><li>总览会混合所选范围内的场景和参数；优先查看同场景明细与单次报告。</li><li>前一周期是等长的相邻时间窗口，环境不一致时变化百分比不能代表性能退化。</li><li>思考模式、缓存命中、提示词和输出长度影响耗时；内置测速使用不同业务问题，缓存是否命中以接口返回为准；能力回归和客户案例保持原样。</li><li>未返回 usage 时，token/s 留空。接口忽略流式参数时，不计算首输出延迟与生成速度。</li><li>不自动重试，避免掩盖首次失败。工具排队耗时与接口耗时分别记录。</li><li>结果代表测试节点到服务入口的表现，不等于客户电脑体验，也不能证明内部模型被更换。</li></ul><h2>能力回归题库 v2 · ${cases.length}题</h2><p>包含同余方程、组合计数、符号变换、数列推导、会议安排和组合逻辑；按明确的最终答案评分。题库成绩用于前后比较，不代表通用智力。每题可重复1—5次，报告保留原始回答供复核。</p>${cases.map((c,i)=>`<details class="quality-item"><summary>${String(i+1).padStart(2,'0')} · ${esc(c.name)}</summary><pre>${esc(c.prompt)}</pre>${c.source_url?`<p><a class="text-button" href="${esc(c.source_url)}" target="_blank" rel="noopener noreferrer">题型来源</a> · ${esc(c.origin||'')}</p>`:''}<p>标准答案：${esc(typeof c.answer==='object'?JSON.stringify(c.answer):c.answer)}</p></details>`).join('')}</div></section><aside class="stack" style="align-content:start"><section class="panel"><div class="panel-body help-content"><h2>部署与数据</h2><p>默认仅本机访问。通过「局域网启动.bat」开放局域网后，需允许 系统防火墙入站端口。公网访问请配置域名、HTTPS 与访问控制。</p><p>数据库、凭证密钥与日志存于部署目录。不要把运行中的数据库放在共享盘或网盘同步文件夹。创建备份后，再复制备份文件夹。</p><p>更新时保留 data 文件夹；迁移时保留 llmirror.db 和 vault.key。重启会将未完成任务标记为中断，不自动重复调用。</p><p>定时采样由本机后台执行。电脑关机、休眠或断网时无法继续；关闭网页不影响后台任务。</p></div></section><section class="panel"><div class="panel-body help-content"><h2>凭证与报告</h2><p>API Key 经加密后存盘。加密密钥也在本机，请限制部署文件夹的访问权限。拥有整套数据文件的人仍可能解密凭证。</p><p>CSV报告不包含提示词、回答及凭证。页面样本包含客户材料，所有工作台成员均可查看，请先脱敏再测试。</p><p>预算在任务创建时预留，不等同于平台结算；停止后仍可能计费。</p></div></section></aside></div>`;}
document.addEventListener('pointermove',e=>{const tip=$('#chart-tooltip');if(!tip)return;const hit=e.target.closest('.chart-hit');if(!hit){tip.hidden=true;return;}tip.textContent=hit.dataset.tip;tip.hidden=false;tip.style.left=Math.max(8,Math.min(e.clientX+14,window.innerWidth-280))+'px';tip.style.top=Math.max(8,Math.min(e.clientY+14,window.innerHeight-tip.offsetHeight-8))+'px';});
document.addEventListener('focusin',e=>{const hit=e.target.closest('.chart-hit'),tip=$('#chart-tooltip');if(!hit||!tip)return;const r=hit.getBoundingClientRect();tip.textContent=hit.dataset.tip;tip.hidden=false;tip.style.left=Math.max(8,Math.min(r.left,window.innerWidth-280))+'px';tip.style.top=Math.max(8,Math.min(r.bottom,window.innerHeight-tip.offsetHeight-8))+'px';});
document.addEventListener('focusout',e=>{if(e.target.closest('.chart-hit')){const tip=$('#chart-tooltip');if(tip)tip.hidden=true;}});
function userDialog(){showDialog(dialogHead('添加同事账号','设置账号权限。')+`<form id="user-form" class="dialog-body"><label class="field"><span>账号</span><input name="username" required minlength="2" maxlength="40" pattern="[a-zA-Z0-9_.@-]+" autocomplete="off"></label><label class="field"><span>初始密码</span><input type="password" name="password" required minlength="6" maxlength="128" autocomplete="new-password"></label><label class="field"><span>权限</span><select name="role"><option value="member">测试成员 · 查看与发起测试</option><option value="viewer">只读成员 · 仅查看结果</option><option value="admin">管理员 · 维护接口、凭证与账号</option></select></label><div class="form-actions"><button class="button primary" type="submit">创建账号</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await busy($('button[type=submit]',e.target),async()=>{try{await api('/users',{method:'POST',body:Object.fromEntries(f)});$('#dialog').close();toast('同事账号已创建');await renderSettings();}catch(err){toast(err.message,true);}});};}
function confirmDialog(title,message,action){showDialog(dialogHead(title)+`<div class="dialog-body"><p class="muted" style="line-height:2">${esc(message)}</p><div class="form-actions"><button class="button" data-action="close-dialog">取消</button><button class="button primary" id="confirm-action">确认</button></div></div>`);$('#confirm-action').onclick=async e=>busy(e.target,async()=>{try{await action();$('#dialog').close();}catch(err){toast(err.message,true);}});}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{
 if(el.dataset.run){if(state.route==='lab')await renderLab(+el.dataset.run);else{state.runEndpoint=+el.dataset.run;location.hash='lab';}}
 if(el.dataset.edit)endpointDialog(state.endpoints.find(x=>x.id===+el.dataset.edit));
 if(el.dataset.delete)confirmDialog('删除这个接口？','历史测试记录会保留，后台定时采样将停止。',async()=>{await api('/endpoints/'+el.dataset.delete,{method:'DELETE',body:{}});state.endpoint=0;toast('接口已删除');await renderEndpoints();});
 if(el.dataset.job)await jobDialog(el.dataset.job);
 if(el.dataset.deleteJob)confirmDialog('删除这条测试记录？','该任务及其样本将被删除，对应看板统计会更新。此操作无法撤销。',async()=>{await api('/jobs/'+el.dataset.deleteJob,{method:'DELETE',body:{}});toast('测试记录已删除');await renderJobs();});
 if(el.dataset.cancel)confirmDialog('停止这个测试任务？','将取消尚未完成的请求。已发送到平台的请求可能已产生用量，今日预留预算不会返还。',async()=>{await api('/jobs/'+el.dataset.cancel+'/cancel',{method:'POST',body:{}});toast('已发送停止指令');await renderJobs();});
 if(el.dataset.deleteUser)confirmDialog('删除同事账号？',`账号 ${el.dataset.username} 的登录将失效，已有测试记录会保留。`,async()=>{await api('/users/'+el.dataset.deleteUser,{method:'DELETE',body:{}});await renderSettings();});
 switch(el.dataset.action){case 'add-endpoint':endpointDialog();break;case 'batch-models':batchModelsDialog();break;case 'close-dialog':$('#dialog').close();break;case 'reload':case 'refresh':await render();break;case 'add-user':userDialog();break;case 'backup':await busy(el,async()=>{const b=await api('/backup',{method:'POST',body:{}});toast('备份已保存到 '+b.folder+'，请妥善保管。');});break;case 'cleanup':confirmDialog('清理过期测试数据？','将按当前保留天数删除已结束任务及样本；此操作不能撤回。',async()=>{await api('/cleanup',{method:'POST',body:{}});toast('过期数据已清理');});break;}
 }catch(err){toast(err.message,true);}});
$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:{}});state.user=null;showAuth(true);}catch(err){toast(err.message,true);}};
$('#help-link').onclick=()=>location.hash='help';
window.addEventListener('hashchange',()=>render());
let poll=0;
setInterval(async()=>{if(!state.user||document.hidden||$('#dialog').open||state.refreshing||!['overview','monitor','jobs'].includes(state.route))return;state.refreshing=true;try{if(state.route==='jobs')await renderJobs();else if(++poll%3===0)await (state.route==='monitor'?renderMonitor():renderOverview());}catch(e){/* Keep the last successful view when the server is temporarily unavailable. */}finally{state.refreshing=false;}},5000);
async function boot(){try{const a=await api('/auth/state');const runtime=$('#runtime-platform');if(runtime)runtime.textContent=(a.platform||'本地')+' / SQLITE';if(a.user){state.user=a.user;state.csrf=a.user.csrf;await enter();window.dispatchEvent(new Event('llmirror-ready'));}else showAuth(a.initialized,a.local);}catch(e){window.dispatchEvent(new Event('llmirror-ready'));$('#auth-box').innerHTML=`<h2>暂时无法连接工作台</h2><p>${esc(e.message)}</p><button class="button primary" id="retry-boot">重试</button>`;$('#retry-boot').onclick=boot;}}
boot();

let chartResizeTimer;
window.addEventListener('resize',()=>{clearTimeout(chartResizeTimer);chartResizeTimer=setTimeout(()=>{if(!state.user||$('#dialog').open)return;if(state.route==='overview')renderOverview().catch(()=>{});else if(state.route==='monitor')renderMonitor().catch(()=>{});},350);});
